          translatingNoteId={translatingNoteId}
        />

        <Fab
          color="primary"
          sx={{ position: 'fixed', bottom: 16, right: 16 }}
          onClick={handleCreateNote}
        >
          <AddIcon />
        </Fab>

        <ConvertToTaskDialog
          open={convertDialogOpen}
          onClose={() => {
            setConvertDialogOpen(false);
            setTranslateSuggestions(null);
