        <OrganizeDialog
          open={organizeDialogOpen}
          onClose={() => {
            setOrganizeDialogOpen(false);
            setOrganizeSuggestions(null);
          }}
          onApply={handleApplyOrganization}
          suggestions={organizeSuggestions}
          loading={organizingNotes}
          notes={notes}
          folders={folders}
        />

