          <Paper sx={{ p: 1.5, minWidth: 220 }}>
            <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
              {activeNote.title}
            </Typography>
          </Paper>
        ) : null}
      </DragOverlay>
    </DndContext>
