    "body": "\naccess key \nAKIA5MYBN2BVHBAN47PL\n\nsecret access key\n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\n\n\naws bedrock create-inference-profile \\\n  --region us-east-1 \\\n  --inference-profile-name pals-jm5676-claude-sonnet-4-5 \\\n  --model-source copyFrom=\"arn:aws:bedrock:us-east-1::foundation-model/anthropic.claude-sonnet-4-5-20250929-v1:0\" \\\n  --tags key=billing-tag1,value=jm5676 key=project,value=pals\n\n\n\narn:aws:bedrock:us-east-1:920736616554:application-inference-profile/sac03yzmleb8\n\n\nimport boto3\nimport json\nimport os\n\n# Create the client (it will auto-discover the bearer token)\nclient = boto3.client(\n\u00a0\u00a0\u00a0\u00a0service_name=\"bedrock-runtime\",\n\u00a0\u00a0\u00a0\u00a0region_name=\"us-east-1\",\u00a0\u00a0# Make sure this matches the region where the key was generated\n)\n\n# Example: Invoke Claude 3 Sonnet via an application inference profile\n# Replace with your profile ARN or ID.\ninference_profile_id = \"arn:aws:bedrock:us-east-1:920736616554:application-inference-profile/sac03yzmleb8\"\n\nresponse = client.invoke_model(\n\u00a0\u00a0\u00a0\u00a0modelId=inference_profile_id,\n\u00a0\u00a0\u00a0\u00a0body=json.dumps(\n\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0{\n\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\"anthropic_version\": \"bedrock-2023-05-31\",\n\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\"max_tokens\": 1000,\n\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\"messages\": [{\"role\": \"user\", \"content\": \"Hello, how are you?\"}],\n\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0}\n\u00a0\u00a0\u00a0\u00a0),\n)\n\nresponse_body = json.loads(response.get(\"body\").read())\nprint(response_body[\"content\"][0][\"text\"])\n\n",
