// ==================== Base Models ====================

export interface NoteActivity {
  type: 'created' | 'updated' | 'moved';
  timestamp: string;
  details?: Record<string, any>;
}

export interface Note {
  id: string;
  title: string;
  body: string;
  is_inspiration: boolean;
  is_analyzed: boolean;
  folder_id: string | null;
  created_at: string;
  updated_at: string;
  activity_history: NoteActivity[];
}

export interface NoteVersion {
  id: string;
  note_id: string;
  version_number: number;
  title: string;
  body: string;
  folder_id: string | null;
  created_at: string;
}

export interface SearchResult {
  note: Note;
  is_version_history: boolean;
  version?: NoteVersion;
  match_snippet?: string;
}

export interface DiffChunk {
  type: 'add' | 'remove' | 'unchanged';
  content: string;
  index: number;
}

export interface DayActivities {
  date: string;
  created: Note[];
  updated: Note[];
  moved: Note[];
}

export interface Folder {
  id: string;
  name: string;
  description: string | null;
  color: string;
  created_at: string;
  updated_at: string;
}

export interface PlannerItem {
  id: string;
  title: string;
  body: string;
  date: string;
  time: string | null;
  view_type: 'daily' | 'weekly' | 'monthly' | 'yearly';
  status: 'pending' | 'completed';
  created_at: string;
  updated_at: string;
}

export interface Task {
  id: string;
  title: string;
  completed: boolean;
  due_date: string | null;
  google_task_id: string | null;
  updated_at: string;
  last_synced_at: string | null;
}

export interface CreateTaskRequest {
  title: string;
  completed?: boolean;
  due_date?: string;
}

export interface UpdateTaskRequest {
  title?: string;
  completed?: boolean;
  due_date?: string;
}

export interface SyncAction {
  action: 'create' | 'update' | 'delete';
  task: Task;
  source: 'local' | 'google';
  reason: string;
}

export interface SyncConflict {
  task_id: string;
  local_task: Task;
  google_task: Task;
  local_updated_at: string;
  google_updated_at: string;
}

export interface SyncPreviewResponse {
  actions: SyncAction[];
  conflicts: SyncConflict[];
  summary: { [key: string]: number };
}

export interface SyncResolution {
  task_id: string;
  resolution: 'use_local' | 'use_google' | 'skip';
}

export interface SyncExecuteResponse {
  created: number;
  updated: number;
  deleted: number;
  skipped: number;
  errors: string[];
}

export interface Inspiration {
  id: string;
  note_id: string;
  category: string;
  ai_confidence: number;
  created_at: string;
}

